import java.util.Scanner;

public class HeightAllTheSame {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int l = scanner.nextInt();
        int r = scanner.nextInt();
        long total = 1L * n * m;
        int mod = 998244353;
        if (total % 2 != 0) {
            long ans = modexp(r - l + 1, total, mod);
            System.out.println(ans);
        } else {
            int k = r - l + 1;
            int e = r / 2 - l / 2;
            if (l % 2 == 0) {
                e++;
            }
            int o = k - e;
            long ans = modexp(e + o, total, mod);
            ans = (ans + modexp(e - o, total, mod)) % mod;
            ans = (ans * modexp(2, mod - 2, mod)) % mod;
            System.out.println(ans);
        }
        scanner.close();
    }

    public static long modexp(long base, long exp, int mod) {
        long result = 1;
        long power = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * power) % mod;
            }
            power = (power * power) % mod;
            e >>= 1;
        }
        return result;
    }
}
