#include <bits/stdc++.h>
using namespace std;

long long modexp(long long base, long long exp, int mod) {
    long long result = 1;
    long long power = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * power) % mod;
        }
        power = (power * power) % mod;
        e >>= 1;
    }
    return result;
}

int main() {
