        cout << ans << "\n";
    } else {
        int k = r - l + 1;
        int e = r / 2 - l / 2;
        if (l % 2 == 0) {
            e++;
        }
        int o = k - e;
        long long ans = modexp(e + o, total, mod);
        ans = (ans + modexp(e - o, total, mod)) % mod;
        ans = (ans * modexp(2, mod - 2, mod)) % mod;
        cout << ans << "\n";
    }
    return 0;
}
